/*
 * LPC2148 SmartX Board - Onboard LED1 Blink
 * P0.12 drives the red LED1 using register-level GPIO.
 * No external wiring required - just press Run!
 */

#include <LPC214x.h>

int main() {
    IO0DIR |= (1 << 12);      // P0.12 = output (LED1)
    while (1) {
        IO0SET = (1 << 12);   // Set P0.12 HIGH - LED ON
        delay_ms(500);
        IO0CLR = (1 << 12);   // Set P0.12 LOW - LED OFF
        delay_ms(500);
    }
}
